CREATE OR REPLACE FUNCTION private.is_workspace_member(_workspace_id uuid, _user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.workspace_members m WHERE m.workspace_id = _workspace_id AND m.user_id = _user_id) $$;
REVOKE ALL ON FUNCTION private.is_workspace_member(uuid,uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION private.is_workspace_member(uuid,uuid) TO authenticated;
DROP POLICY "team creates collaboration tasks" ON public.collaboration_tasks;
CREATE POLICY "team creates collaboration tasks" ON public.collaboration_tasks FOR INSERT TO authenticated WITH CHECK ((public.owns_workspace(workspace_id) OR private.is_workspace_member(workspace_id)) AND created_by = auth.uid() AND (assignee_id IS NULL OR assignee_id = (SELECT owner_id FROM public.workspaces WHERE id = workspace_id) OR private.is_workspace_member(workspace_id, assignee_id)));
DROP POLICY "team edits collaboration tasks" ON public.collaboration_tasks;
CREATE POLICY "team edits collaboration tasks" ON public.collaboration_tasks FOR UPDATE TO authenticated USING (public.owns_workspace(workspace_id) OR private.is_workspace_member(workspace_id)) WITH CHECK ((public.owns_workspace(workspace_id) OR private.is_workspace_member(workspace_id)) AND (assignee_id IS NULL OR assignee_id = (SELECT owner_id FROM public.workspaces WHERE id = workspace_id) OR private.is_workspace_member(workspace_id, assignee_id)));
CREATE FUNCTION public.protect_collaboration_identity() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.workspace_id IS DISTINCT FROM OLD.workspace_id OR NEW.created_by IS DISTINCT FROM OLD.created_by OR (TG_TABLE_NAME = 'collaboration_tasks' AND NEW.project_id IS DISTINCT FROM OLD.project_id) THEN RAISE EXCEPTION 'Collaboration ownership cannot be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_collaboration_projects BEFORE UPDATE ON public.collaboration_projects FOR EACH ROW EXECUTE FUNCTION public.protect_collaboration_identity();
CREATE TRIGGER protect_collaboration_tasks BEFORE UPDATE ON public.collaboration_tasks FOR EACH ROW EXECUTE FUNCTION public.protect_collaboration_identity();